def minimumCost(target: str, words: list[str], costs: list[int]) -> int:
    # A trie will store all the words we can use to construct the target string.
    # Each node in the trie is a dictionary where keys are characters and 
    # one special key '#' stores the minimum cost of a word ending at that node.
    trie = {}
    for w, c in zip(words, costs):
        node = trie
        for char in w:
            if char not in node:
                node[char] = {}
            node = node[char]
        # If multiple words are the same, we only care about the one with the minimum cost.
        if '#' not in node or c < node['#']:
            node['#'] = c

    n = len(target)
    # dp[i] stores the minimum cost to construct target[:i].
    # Initialize with a very large number representing infinity.
    dp = [float('inf')] * (n + 1)
    dp[0] = 0

    for i in range(n):
        # If it's impossible to reach the current position, skip it.
        if dp[i] == float('inf'):
            continue

        node = trie
        # Explore all possible words starting from target[i].
        # Since we only traverse paths that exist in our Trie, 
        # and the sum of word lengths is small, this DP approach is efficient.
        for j in range(i, n):
            char = target[j]
            if char not in node:
                break
            node = node[char]
            # If a word ends at the current prefix match, update dp[j+1].
            if '#' in node:
                cost_to_reach_next = dp[i] + node['#']
                if cost_to_reach_next < dp[j + 1]:
                    dp[j + 1] = cost_to_reach_next

    # If the target cannot be constructed, return -1.
    return int(dp[n]) if dp[n] != float('inf') else -1

