from typing import List

def canTraverseAllPairs(nums: List[int]) -> bool:
    # Edge case: A single element is always connected to itself
    if len(nums) <= 1:
        return True

    # If there's a 1 in the list and length > 1, it can never be connected
    # because gcd(1, x) = 1 for all x.
    if 1 in nums:
        return False

    max_num = max(nums)
    # Precompute Smallest Prime Factor (SPF) using a sieve
    spf = list(range(max_num + 1))
    for i in range(2, int(max_num**0.5) + 1):
        if spf[i] == i:
            for j in range(i*i, max_num + 1, i):
                if spf[j] == j:
                    spf[j] = i

    # DSU (Disjoint Set Union) structure to group prime factors
    parent = list(range(max_num + 1))
    def find(i):
        if parent[i] == i:
            return i
        parent[i] = find(parent[i])
        return parent[i]

    def union(i, j):
        root_i = find(i)
        root_j = find(j)
        if root_i != root_j:
            parent[root_i] = root_j

    # Track all prime factors present in the input array
    used_primes = set()

    for x in nums:
        factors = []
        temp = x
        # Factorize x using the SPF array
        while temp > 1:
            p = spf[temp]
            factors.append(p)
            used_primes.add(p)
            while temp % p == 0:
                temp //= p

        # Union all prime factors of the current number
        # This connects all numbers sharing these primes into one component
        for i in range(len(factors) - 1):
            union(factors[i], factors[i+1])

    if not used_primes:
        return True

    # Check if all used prime factors belong to the same connected component
    # If they do, it means all numbers are reachable from each other.
    root = -1
    for p in used_primes:
        current_root = find(p)
        if root == -1:
            root = current_root
        elif root != current_root:
            return False

    return True

